-- Seed 21 societies, one per CITY_HUB (20 + Siliguri), embedded in Supabase
on conflict (city, name) do update set
  hub_id=excluded.hub_id, state=excluded.state, location=excluded.location,
  manager_name=excluded.manager_name, units=excluded.units, blocks=excluded.blocks,
  stats=excluded.stats, coords=excluded.coords, pincode=excluded.pincode;
